def parse(t): return {a.split("|")[0]: int(a.split("|")[1]) for a in t.split(";")}
M, R, S = parse(math_t), parse(read_t), parse(sci_t)
print(len(M), len(R), len(S))
oecd = set("Australia;Austria;Belgium;Canada;Chile;Colombia;Costa Rica;Czechia;Denmark;Estonia;Finland;France;Germany;Greece;Hungary;Iceland;Ireland;Israel;Italy;Japan;Korea;Latvia;Lithuania;Luxembourg;Mexico;Netherlands;New Zealand;Norway;Poland;Portugal;Slovak Republic;Slovenia;Spain;Sweden;Switzerland;Türkiye;United Kingdom;United States".split(";"))
names = sorted(set(M) | set(R) | set(S))
assert oecd <= set(names), oecd - set(names)
print(len(names), len(oecd))
with open("data/evidence_pisa2025_country_tables.csv", "w", newline="") as f:
    w = csv.writer(f)
    w.writerow(["system", "oecd_member", "mathematics", "reading", "science", "source", "status"])
    for n in names:
        w.writerow([n, int(n in oecd), M.get(n, ""), R.get(n, ""), S.get(n, ""), "OECD PISA 2025 Vol I Tables I.B1.2a.3/I.B1.2a.2/I.2.1 as reproduced by eduscores.org", "secondary_reproduction"])
